{"point":{"id":"runtime","title":"Runtime Composition and APIs","rationale":"The backend composition root connects application services to filesystem stores, model runtimes, browser bridges, and language services. Its Vite adapter exposes the core and mapping APIs, translates errors, controls optional capabilities, and owns shutdown. This is the strongest anchor for understanding deployment and dependency wiring.","sourcePaths":["src/server/app/bootstrap.ts","src/server/app/vitePlugin.ts","src/server/routes/core/routes.ts","src/server/routes/mapping/routes.ts","vite.config.ts","tests/architecture/dependencies.test.ts"],"relationships":[{"pointId":"storage","label":"Constructs and injects durable repositories","kind":"ownership"},{"pointId":"agent-api","label":"Wires canvas services and WebSocket transport","kind":"ownership"},{"pointId":"chat","label":"Constructs chat runtime and tool bindings","kind":"ownership"},{"pointId":"changes","label":"Connects push ingestion to proposal workflows","kind":"ownership"},{"pointId":"evals","label":"Assembles evaluation services and generation reconciliation","kind":"ownership"}]},"sources":[{"path":"src/server/app/bootstrap.ts","text":"import { ExperimentService, type StoredExperiment } from '../../../application/mapping/evals/experimentService';
